  let aS1=0,iS1=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src1){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS1+=Math.sin(d*f-t*sp);iS1+=Math.sin(d*f*0.65+t*sp*0.55+1.8);}
  for(const[sX,sY,f,sp]of src2){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS2+=Math.sin(d*f-t*sp);iS2+=Math.sin(d*f*0.6+t*sp*0.5+2.2);}
  const act1=aS1/6,inh1=iS1/6,act2=aS2/4,inh2=iS2/4;
  const bg1=(Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*1.0))/2;
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.08-t*1.8)*0.25;
  const bg3=Math.sin(sx*0.07+Math.sin(sy*0.05+t*0.3)*2+t*1.5)*0.15;
