  const reaction=Math.tanh((r1+r2*0.4+cross)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t*0.7)*0.5+Math.sin(sx*0.2-sy*0.18+t*0.5)*0.3)*1.4)*0.25;
  const moire=Math.sin(dist*0.15)*Math.sin(ang*5+t*0.8)*0.15;
